"""Standalone independent economic recursion and published-output checks."""
import io, contextlib
_buffer = io.StringIO()
with contextlib.redirect_stdout(_buffer):
    exec(compile("#!/usr/bin/env python3\n# Independent literal reconstruction of adopted no-recession endpoints; no model import.\nimport json\n\ndef calc(nimshift,credit,discount):\n A=1498.724641;B=93.150335;dep=1074.078584;wh=294.295722;at=11;re=45.141166;general=19.470453\n total=0;cash=[];gap=.169347\n for year in range(1,401):\n  fade=min(1,max(0,(year-5)/10));growth=.06-.03*fade;endA=A*(1+growth);avg=(A+endA)/2\n  endAT=11*endA/1498.724641;endT=26.2*endA/1498.724641\n  revenue=avg*.94*(.0165-.001*fade+nimshift)+(B-93.150335/1498.724641*A)*.017+avg*.0012\n  profit=(revenue*.76-avg*.0002-avg*.6*credit-avg*.00007)*.84-(at+endAT)/2*(.0228 if year<=3 else .03)\n  # Mother CET target is the active capital requirement in these core paths;\n  # independently verify the other five inequalities after distribution.\n  gap+=.02*endA/1498.724641\n  req=.092*1043.559058/1498.724641*endA+gap+1.120146*endA/1498.724641\n  available=B+profit-req\n  generalAdd=max(0,19.470453/1498.724641*endA-general)\n  legal=re+profit-.02*endA/1498.724641-generalAdd\n  capWh=max(wh*(1+growth),.20*endA);endDep=dep*(1+growth)\n  fund=B+profit+endAT+endT+endDep+capWh-endA\n  payout=max(.3*profit,max(0,available)*min(1,max(0,(year-5)/10)))\n  distribution=max(0,min(payout,available,legal,fund,(.116-.06966*1.2)*endA))\n  B+=profit-distribution;re+=profit-.02*endA/1498.724641-generalAdd-distribution;general+=generalAdd\n  wh=endA-B-endAT-endT-endDep;dep=endDep;A=endA;at=endAT\n  parent=B-gap-1.120146*A/1498.724641;group=B+.675043*A/1498.724641\n  assert parent/(1043.559058/1498.724641*A)>=.092-1e-10\n  assert (parent+at)/(1043.559058/1498.724641*A)>=.102-1e-10\n  assert (parent+at+endT+12.324414*A/1498.724641)/(1043.559058/1498.724641*A)>=.135-1e-10\n  assert group/(1060.159861/1498.724641*A)>=.092-1e-10\n  assert (group+at+.118678*A/1498.724641)/(1060.159861/1498.724641*A)>=.102-1e-10\n  assert (group+at+endT+12.859437*A/1498.724641)/(1060.159861/1498.724641*A)>=.135-1e-10\n  total+=distribution/(1+discount)**year/4.238435356\n  if year<=5:cash.append(distribution/4.238435356)\n return dict(value=total,distributions=cash)\nif __name__=='__main__':\n out={'core_low_11.5':calc(-.0003,.0055,.115),'core_high_10.5':calc(.0003,.0045,.105),'base_11':calc(0,.005,.11),'nim_minus10bp_11':calc(-.001,.005,.11)}\n print(json.dumps(out,indent=2))\n", __file__, "exec"), {"__file__": __file__, "__name__": "__main__"})
print(_buffer.getvalue())
exec(compile("from pathlib import Path\nfrom decimal import Decimal as D,getcontext\nimport json\ngetcontext().prec=40\nout=json.load(open(str(Path(__file__).resolve().parent / '2026-Q3-output.json')))\nresults=[]\nfor case,shift,cc in [('base','0','.005'),('core_low','-.0003','.0055'),('core_high','.0003','.0045'),('nim_minus10bp','-.001','.005')]:\n a=D('1498.724641');a0=a;e=D('93.150335');pe=D('92.980988');dep=D('1074.078584');w=D('294.295722');at=D(11);re=D('45.141166');gr=D('19.470453');errs=[];ds=[]\n for t in range(1,401):\n  fade=min(D(1),max(D(0),(D(t)-5)/10));growth=D('.06')-D('.03')*fade\n  an=a*(1+growth);z=an/a0;avg=(a+an)/2;atn=11*z;tn=D('26.2')*z\n  revenue=avg*D('.94')*(D('.0165')-D('.001')*fade+D(shift))+(e-D('93.150335')/a0*a)*D('.017')+avg*D('.0012')\n  p=(revenue*D('.76')-avg*D('.0002')-avg*D('.60')*D(cc)-avg*D('.00007'))*D('.84')-(at+atn)/2*(D('.0228') if t<=3 else D('.03'))\n  pp=p-D('.020')*z;gap=e-pe+D('.020')*z\n  rp=D('1043.559058')*z;rg=D('1060.159861')*z;ded=D('1.120146')*z\n  req=max(D('.092')*rp+gap+ded,D('.102')*rp-atn+gap+ded,D('.135')*rp-atn-tn-D('12.324414')*z+gap+ded,D('.092')*rg-D('.675043')*z,D('.102')*rg-atn-D('.793721')*z,D('.135')*rg-atn-tn-D('13.534480')*z)\n  cap=e+p-req;gn=max(D(0),D('19.470453')*z-gr);dn=dep*(1+growth);wc=max(w*(1+growth),D('.2')*an)\n  div=max(D(0),min(max(D('.3')*p,max(D(0),cap)*fade),cap,re+pp-gn,e+p+atn+tn+dn+wc-an,(D('.116')-D('.06966')*D('1.2'))*an*D('0.9963')))\n  e+=p-div;pe+=pp-div;re+=pp-gn-div;gr+=gn;w=an-e-atn-tn-dn;dep=dn;a=an;at=atn;ds.append(div/D('4.238435356'))\n  actual=out['cases'][case]['years'][t-1]\n  for k,v in {'A':a,'E':e,'PE':pe,'profit':p,'parent_profit':pp,'RE':re,'dividend':div,'W':w}.items():errs.append(abs(float(v)-actual[k]))\n for rate in ['.105','.11','.115']:\n  r=D(rate);pv=sum(x/(1+r)**(i+1) for i,x in enumerate(ds));expected=out['cases'][case]['values'][str(float(r))]['ddm'];assert abs(float(pv)-expected)<1e-8\n results.append({'case':case,'annual_fields':3200,'maximum_absolute_error':max(errs)})\n assert max(errs)<.00001\nprint(json.dumps(results,indent=2))\n", __file__, "exec"), {"__file__": __file__, "__name__": "__main__", "_AUTHOR_JSON": _buffer.getvalue()})
exec(compile("from pathlib import Path\nimport importlib.util,json\np=str(Path(__file__).resolve().parent / '2026-Q3.py');sp=importlib.util.spec_from_file_location('m',p);m=importlib.util.module_from_spec(sp);sp.loader.exec_module(m)\ns=dict(A=100.,E=10.,D=80.,W=10.,AT=0.,T=0.,RE=-5.,SR=5.,GR=0.)\nx=m.params(1);x.update(g=0,dg=0,wg=0,profit=4,release=1)\na=m.advance(s,x,1,True)\nassert a['RE']==-1 and a['dividend']==0\nb=m.advance(a,x,2,True);assert abs(b['dividend']-3)<1e-10\ns['SR']=0;c=m.advance(s,x,1,True);d=m.advance(c,x,2,True)\nassert c['SR']==0 and c['dividend']==0 and abs(d['SR']-.3)<1e-10 and abs(d['dividend']-2.7)<1e-10\nprint(json.dumps({'deficit_then_profit_full_production':True,'capped_dividends':[a['dividend'],b['dividend']],'uncapped_dividends':[c['dividend'],d['dividend']]}))\n", __file__, "exec"), {"__file__": __file__, "__name__": "__main__"})
